('<lesson_id>', 'quiz', replace($blk${"questions": [{"q": "Супер-пупер! Прочитай вопрос и выбери правильный ответ. Are you sending an email? Yes, I ___.", "type": "single", "options": [{"text": "is"}, {"text": "am"}, {"text": "are"}], "correct": [1]}, {"q": "Is he doing his homework? Yes, he ___.", "type": "single", "options": [{"text": "is"}, {"text": "am"}, {"text": "are"}], "correct": [0]}, {"q": "Is she listening to music? No, she ___.", "type": "single", "options": [{"text": "am not"}, {"text": "aren't"}, {"text": "isn't"}], "correct": [2]}, {"q": "Are you having lunch? Yes, we ___.", "type": "single", "options": [{"text": "am"}, {"text": "are"}, {"text": "is"}], "correct": [1]}, {"q": "Are they wearing hats? No, they ___.", "type": "single", "options": [{"text": "aren't"}, {"text": "am not"}, {"text": "isn't"}], "correct": [0]}, {"q": "Am I dreaming? No, you ___.", "type": "single", "options": [{"text": "am not"}, {"text": "isn't"}, {"text": "aren't"}], "correct": [2]}]}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 10),
