('<lesson_id>', 'text', replace($blk${"html": "<p>Уррра!! Домашняя работа сделана. Для тебя есть ещё дополнительное задание. Ты можешь его не делать, но оно супер интересное. Нужно помочь лягушке 🐸 добраться до берега, отвечая на вопросы.</p>"}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 18),
('<lesson_id>', 'quiz', replace($blk${"questions": [{"q": "🐸 Попробуй, тебе понравится! ___ you watching TV? — Yes, I am.", "type": "single", "options": [{"text": "Is"}, {"text": "Are"}, {"text": "Am"}], "correct": [1]}, {"q": "🐸 Is your dad cooking dinner? — No, he ___.", "type": "single", "options": [{"text": "isn't"}, {"text": "aren't"}, {"text": "doesn't"}], "correct": [0]}, {"q": "🐸 What ___ they doing? — They're playing football.", "type": "single", "options": [{"text": "is"}, {"text": "do"}, {"text": "are"}], "correct": [2]}, {"q": "🐸 ___ I talking too loudly? — No, you aren't.", "type": "single", "options": [{"text": "Am"}, {"text": "Is"}, {"text": "Are"}], "correct": [0]}, {"q": "🐸 Are your friends chatting online? — Yes, they ___.", "type": "single", "options": [{"text": "is"}, {"text": "are"}, {"text": "do"}], "correct": [1]}, {"q": "🐸 Where ___ Anna going? — To the park.", "type": "single", "options": [{"text": "are"}, {"text": "does"}, {"text": "is"}], "correct": [2]}, {"q": "🐸 Is the cat sleeping? — Yes, it ___.", "type": "single", "options": [{"text": "is"}, {"text": "does"}, {"text": "are"}], "correct": [0]}, {"q": "🐸 Why ___ you running? — Because I'm late!", "type": "single", "options": [{"text": "is"}, {"text": "are"}, {"text": "do"}], "correct": [1]}]}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 19),
('<lesson_id>', 'text', replace($blk${"html": "<p><img src=\"@@MEDIA@@shared/well_done_clap.webp\" alt=\"\" style=\"height:200px\"></p><h2>Ты заслуживаешь большой-большой похвалы!</h2><p>Вся твоя домашняя работа сделана. Самое время немножко отдохнуть. Увидимся на занятии 😉</p>"}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 20)
